-- K99 (D223): the voice catalog. Run after 20261117230001_k99_mix_review.sql (needs the review column).
-- From ElevenLabs' voice library (listing only, no credits). Verified: name, description, accent and preview_url
-- as the library lists them. NOT verified: how each voice sounds reading Swedish; whether a library voice works
-- for TTS before it is added to the account. Kines/Hindi and the caricatures are review=true (admin only) until Aron has listened.
on conflict (voice_id) do update set name=excluded.name, gender=excluded.gender, age=excluded.age, accent=excluded.accent,
  language=excluded.language, preview_url=excluded.preview_url, description=excluded.description, sort=excluded.sort, review=excluded.review, enabled=true;
